export function AccessControl({
  panelTitle = "{{panelTitle}}",
  role = "{{role}}",
  accent = "{{accent}}",
  showDeniedNote = {{showDeniedNote}},
}) {
  const canEdit = role === "editor" || role === "admin";
  const canDelete = role === "admin";
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ fontWeight: 700, marginBottom: 12, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        {panelTitle} <span style={{ fontSize: 10, fontWeight: 600, textTransform: "uppercase", background: "#24143014", padding: "3px 8px", borderRadius: 999 }}>{role}</span>
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <button type="button" style={{ border: "none", padding: "9px 14px", borderRadius: 8, fontWeight: 600, fontSize: 12, cursor: "pointer", background: accent }}>View</button>
        {canEdit && <button type="button" style={{ border: "none", padding: "9px 14px", borderRadius: 8, fontWeight: 600, fontSize: 12, cursor: "pointer", background: "#24143014", color: "#241430" }}>Edit</button>}
        {canDelete && <button type="button" style={{ border: "none", padding: "9px 14px", borderRadius: 8, fontWeight: 600, fontSize: 12, cursor: "pointer", background: "#241430", color: "#FAF7F2" }}>Delete</button>}
      </div>
      {showDeniedNote && <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>Buttons a {role} cannot use are hidden entirely, not just disabled.</p>}
    </div>
  );
}
